# stream/schema.py
import json
from datetime import datetime, timezone

from pydantic import BaseModel, Field

SCHEMA_VERSION = 1


class OrderEvent(BaseModel):
    schema_version: int = SCHEMA_VERSION
    order_id: int
    customer_id: int
    amount: float = Field(gt=0)
    status: str = "placed"           # placed | cancelled
    event_time: float                # unix seconds; when the order happened, not when it was sent

    def key(self) -> bytes:
        return str(self.customer_id).encode()

    def serialize(self) -> bytes:
        return self.model_dump_json().encode()


def deserialize(raw: bytes) -> OrderEvent:
    return OrderEvent.model_validate_json(raw)


def iso(ts: float) -> str:
    return datetime.fromtimestamp(ts, timezone.utc).isoformat()

