from dataclasses import dataclass, field


def window_start(event_time: float, size: int) -> int:
    """The start (unix second) of the tumbling window this event belongs to."""
    return int(event_time // size) * size


@dataclass
class Aggregate:
    orders: int = 0
    revenue: float = 0.0
    cancellations: int = 0

    def add(self, amount: float, status: str) -> None:
        self.orders += 1
        if status == "cancelled":
            self.cancellations += 1
        else:
            self.revenue += amount


@dataclass
class WindowState:
    size: int = 60                 # one-minute windows
    allowed_lateness: int = 120    # accept events up to 2 minutes late
    watermark: float = 0.0
    windows: dict[int, Aggregate] = field(default_factory=dict)
    dropped_late: int = 0

    def observe(self, event_time: float, amount: float, status: str) -> None:
        self.watermark = max(self.watermark, event_time - self.allowed_lateness)
        start = window_start(event_time, self.size)
        if start + self.size <= self.watermark:
            self.dropped_late += 1        # too late: its window has already been finalised
            return
        self.windows.setdefault(start, Aggregate()).add(amount, status)

    def closed(self) -> list[tuple[int, Aggregate]]:
        """Windows the watermark has passed; caller emits then removes them."""
        return [(s, a) for s, a in sorted(self.windows.items()) if s + self.size <= self.watermark]

    def evict(self, starts: list[int]) -> None:
        for s in starts:
            self.windows.pop(s, None)
